11	export class AboutTheatreAutoplayRuntime {
12	  private _previewDispose: (() => void) | null = null;
13	  private _previewTask: Promise<void> | null = null;
14	  private _autoplayDispose: (() => void) | null = null;
15	  private _autoplayTask: Promise<void> | null = null;
16	
17	  constructor(
18	    private readonly _applyState: (engine: Engine, values: AboutTheatreValue) => void,
19	  ) {}
20	
21	  startPreview(
22	    engine: Engine,
23	    sheetIds: readonly AboutTheatreSheetId[],
24	    resolveBinding: (sheetId: AboutTheatreSheetId) => AboutTheatreSheetBinding | null,
25	    resolveRange: (
26	      sheetId: AboutTheatreSheetId,
27	      length: number,
28	    ) => AboutTheatrePlaybackRange | null,
29	    rate: number,
30	  ): Promise<void> {
31	    if (this._previewTask) return this._previewTask;
32	    this._previewTask = this._runPreview(
33	      engine,
34	      sheetIds,
35	      resolveBinding,
36	      resolveRange,
37	      rate,
38	    ).finally(() => {
39	      this._previewDispose?.();
40	      this._previewDispose = null;
41	      this._previewTask = null;
42	    });
43	    return this._previewTask;
44	  }
45	
46	  stopPreview(bindings: Iterable<TheatreSequencePort>): void {
47	    this._previewDispose?.();
48	    this._previewDispose = null;
49	    this._autoplayDispose?.();
50	    this._autoplayDispose = null;
51	    for (const sequence of bindings) {
52	      sequence.pause();
53	    }
54	  }
55	
56	  startSheetAutoplay(
57	    engine: Engine,
58	    options: {
59	      sheetId: AboutTheatreSheetId;
60	      resolveBinding: (sheetId: AboutTheatreSheetId) => AboutTheatreSheetBinding | null;
61	      resolveRange: (
62	        sheetId: AboutTheatreSheetId,
63	        length: number,
64	      ) => AboutTheatrePlaybackRange;
65	      rate: number;
66	      fallbackSync: (engine: Engine) => void;
67	      completeSync: (engine: Engine, position: number) => void;
68	    },
69	  ): Promise<void> {
70	    if (this._autoplayTask) return this._autoplayTask;
71	    this._autoplayTask = this._runSheetAutoplay(engine, options).finally(() => {
72	      this._autoplayDispose?.();
73	      this._autoplayDispose = null;
74	      this._autoplayTask = null;
75	    });
76	    return this._autoplayTask;
77	  }
78	
79	  private async _runPreview(
80	    engine: Engine,
81	    sheetIds: readonly AboutTheatreSheetId[],
82	    resolveBinding: (sheetId: AboutTheatreSheetId) => AboutTheatreSheetBinding | null,
83	    resolveRange: (
84	      sheetId: AboutTheatreSheetId,
85	      length: number,
86	    ) => AboutTheatrePlaybackRange | null,
87	    rate: number,
88	  ): Promise<void> {
89	    for (const sheetId of sheetIds) {
90	      const binding = resolveBinding(sheetId);
91	      if (!binding || binding.length <= 0) continue;
92	      const playbackRange = resolveRange(sheetId, binding.length);
93	      if (!playbackRange) continue;
94	      binding.sequence.position = playbackRange.start;
95	      this._previewDispose?.();
96	      this._previewDispose = TheatrePlaybackService.bindValues(
97	        binding.object,
98	        (values) => {
99	          this._applyState(engine, values);
100	        },
101	      );
102	      this._applyState(engine, binding.object.value);
103	      await binding.sequence.play({
104	        range: [playbackRange.start, playbackRange.end],
105	        rate,
106	      });
107	    }
108	  }
109	
110	  private async _runSheetAutoplay(
111	    engine: Engine,
112	    options: {
113	      sheetId: AboutTheatreSheetId;
114	      resolveBinding: (sheetId: AboutTheatreSheetId) => AboutTheatreSheetBinding | null;
115	      resolveRange: (
116	        sheetId: AboutTheatreSheetId,
117	        length: number,
118	      ) => AboutTheatrePlaybackRange;
119	      rate: number;
120	      fallbackSync: (engine: Engine) => void;
121	      completeSync: (engine: Engine, position: number) => void;
122	    },
123	  ): Promise<void> {
124	    const binding = options.resolveBinding(options.sheetId);
125	    if (!binding) {
126	      options.fallbackSync(engine);
127	      return;
128	    }
129	    const playbackRange = options.resolveRange(
130	      options.sheetId,
131	      binding.length,
132	    );
133	    if (playbackRange.end <= playbackRange.start) {
134	      options.fallbackSync(engine);
135	      return;
136	    }
137	
138	    binding.sequence.pause();
139	    binding.sequence.position = playbackRange.start;
140	    this._autoplayDispose?.();
141	    this._autoplayDispose = TheatrePlaybackService.bindValues(
142	      binding.object,
143	      (values) => {
144	        this._applyState(engine, values);
145	      },
146	    );
147	    this._applyState(engine, binding.object.value);
148	    await binding.sequence.play({
149	      range: [playbackRange.start, playbackRange.end],
150	      rate: options.rate,
151	    });
152	    binding.sequence.pause();
153	    options.completeSync(engine, playbackRange.end);
154	  }
155	}
