93	  const cameraSheet = readAboutRecord(sheetsById?.heroIntro);
94	  const sequence = readAboutRecord(cameraSheet?.sequence);
95	  const staticOverrides = readAboutRecord(sequence?.staticOverrides);
96	  const objectsByKey = readAboutRecord(staticOverrides?.byObject);
97	  const cameraObject = readAboutRecord(objectsByKey?.[ABOUT_THEATRE_OBJECT_ID]);
